int size_initial = 5;
int size_target = 10;

// Initial allocation
int* arr = malloc(sizeof(int) * size_initial);

// Ensure memory exists
if (arr == NULL) { /* Handle error */ }

// Attempt to resize memory
size_t new_bytes = sizeof(int) * size_target;
int* temp = realloc(arr, new_bytes);

if (temp != NULL) {
    // Success: 'arr' now points to the larger block
    arr = temp;
    arr[size_target - 1] = 42;
} else {
    // Failure: Original 'arr' block remains valid
    // Freeing the old block is still required if exiting
}

free(arr);
